WITH unpacked AS (SELECT id, created_at, ship_to, attributes, ARRAY_MAX(TRANSFORM(items, i -> i.price)) AS max_item_price, EXISTS(items, i -> i.price > 100) AS has_premium_item FROM carts) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, ROUND(AVG(max_item_price), 2) AS avg_max_item_price, COUNT(DISTINCT id) AS distinct_ids, PERCENTILE_APPROX(max_item_price, 0.95) AS max_item_price_p95, ROUND(AVG(max_item_price), 2) AS avg_max_item_price_2, ROUND(AVG(max_item_price), 2) AS avg_max_item_price_3 FROM unpacked GROUP BY 1;
